"""Migrated Meridian CRM opportunity_pipeline workflow."""

from typing import Any


def _amount_is_positive(record: dict) -> bool:
    """Evaluate VRL: NVL(AMT, 0) > 0."""
    value: Any = record.get("AMT", 0)
    if value is None or value == "":
        value = 0

    try:
        return float(value) > 0
    except (TypeError, ValueError):
        return False


def _has_close_date(record: dict) -> bool:
    """Evaluate VRL: CLOSE_DT <> '00000000'."""
    return record.get("CLOSE_DT", "") != "00000000"


def _has_loss_reason(record: dict) -> bool:
    """Evaluate VRL: LOST_RSN <> ''."""
    value = record.get("LOST_RSN", "")
    return isinstance(value, str) and value != ""


def fire(state: str, event: str, record: dict) -> dict:
    """Fire the first matching opportunity_pipeline transition."""
    result_record = dict(record)

    transitions = (
        ("P", "qualify", "Q", _amount_is_positive, (("set", "STAGE_PCT", "25"), ("audit", "OPP_QUAL"))),
        ("Q", "advance", "N", None, (("set", "STAGE_PCT", "60"),)),
        (
            "N",
            "close_won",
            "W",
            _has_close_date,
            (
                ("set", "STAGE_PCT", "100"),
                ("audit", "OPP_WON"),
                ("notify", "won_deal"),
            ),
        ),
        ("P", "close_lost", "L", _has_loss_reason, (("set", "STAGE_PCT", "0"), ("audit", "OPP_LOST"))),
        ("Q", "close_lost", "L", _has_loss_reason, (("set", "STAGE_PCT", "0"), ("audit", "OPP_LOST"))),
        ("N", "close_lost", "L", _has_loss_reason, (("set", "STAGE_PCT", "0"), ("audit", "OPP_LOST"))),
    )

    for from_state, transition_event, to_state, guard, actions in transitions:
        if state != from_state or event != transition_event:
            continue
        if guard is not None and not guard(record):
            continue

        audits = []
        notifies = []
        for action in actions:
            kind = action[0]
            if kind == "set":
                result_record[action[1]] = action[2]
            elif kind == "audit":
                audits.append(action[1])
            elif kind == "notify":
                notifies.append(action[1])

        return {
            "state": to_state,
            "record": result_record,
            "audits": audits,
            "notifies": notifies,
            "matched": True,
        }

    return {
        "state": state,
        "record": result_record,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
